/**
 * Shared timing for the speaking animation used by the player and NPCs.
 *
 * The mouth flaps quickly in an irregular pattern while a hand gesture comes
 * and goes more slowly. The result is one of the frames generated by the
 * sprite compositor: idle (mouth closed, no gesture), talk1 (mouth open),
 * talk2 (mouth open + gesture) or talk3 (mouth closed + gesture).
 */

export type TalkFrame = "idle" | "talk1" | "talk2" | "talk3";

/** Mouth flap pattern (1 = open), one step per MOUTH_STEP_MS. */
export const MOUTH_PATTERN = [1, 0, 1, 1, 0, 1, 0, 0, 1, 0];
export const MOUTH_STEP_MS = 120;
/** How long each hand gesture / rest phase lasts. */
export const GESTURE_PHASE_MS = 900;

/** Pick the talk frame for a speaker who started talking `elapsedMs` ago. */
export function talkFrameAt(elapsedMs: number): TalkFrame {
  const t = Math.max(0, elapsedMs);
  const step = Math.floor(t / MOUTH_STEP_MS) % MOUTH_PATTERN.length;
  const mouthOpen = MOUTH_PATTERN[step] === 1;
  const gesturing = Math.floor(t / GESTURE_PHASE_MS) % 2 === 1;
  if (gesturing) return mouthOpen ? "talk2" : "talk3";
  return mouthOpen ? "talk1" : "idle";
}
